* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #111827; color: #f3f4f6; }
body { min-height: 100vh; margin: 0; display: grid; place-items: center; padding: 24px 16px; background: radial-gradient(ellipse at 50% 0%, #26334d 0, #111827 58%); }
.lock-card { width: min(100%, 440px); padding: 36px 32px 28px; text-align: center; border: 1px solid #39465d; border-radius: 18px; background: #1b2537; box-shadow: 0 24px 70px #080d18aa; }
.pixel-mark { width: 40px; height: 40px; margin: 0 auto 20px; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; transform: rotate(-5deg); }
.pixel-mark span { background: #55e6b5; border-radius: 3px; }
.pixel-mark span:nth-child(2), .pixel-mark span:nth-child(3) { opacity: .55; }
.eyebrow { margin: 0 0 10px; color: #55e6b5; font-size: 12px; font-weight: 800; letter-spacing: .16em; }
h1 { margin: 0; font-size: clamp(25px, 7vw, 32px); line-height: 1.2; }
.intro { margin: 12px 0 26px; color: #b7c2d3; font-size: 16px; line-height: 1.5; }
.dials { display: flex; justify-content: center; gap: clamp(12px, 5vw, 24px); margin: 0 auto 28px; }
.dial { width: 94px; display: grid; justify-items: center; gap: 8px; }
.step-button { width: 48px; height: 40px; border: 1px solid #43516a; border-radius: 10px; background: #26334a; color: #d6e2f2; font: inherit; font-size: 17px; cursor: pointer; transition: background .15s, transform .15s, border-color .15s; }
.step-button:hover { background: #34445f; border-color: #55e6b5; }
.step-button:active { transform: translateY(2px); background: #43516a; }
.digit { width: 74px; padding: 8px 0 10px; border: 1px solid #43516a; border-radius: 12px; background: #101827; color: #55e6b5; font: 700 38px/1.2 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; box-shadow: inset 0 2px 8px #060a11; }
.dial-label { margin-top: 2px; color: #9aa9bf; font-size: 11px; font-weight: 800; letter-spacing: .12em; }
.open-button { width: 100%; min-height: 54px; padding: 12px 18px; display: flex; align-items: center; justify-content: center; gap: 10px; border: 0; border-radius: 11px; background: #55e6b5; color: #10251f; font: 800 16px/1 system-ui, sans-serif; letter-spacing: .06em; cursor: pointer; transition: background .15s, transform .15s, box-shadow .15s; }
.open-button:hover { background: #78f0c8; box-shadow: 0 6px 22px #55e6b544; }
.open-button:active { transform: translateY(2px); background: #39c99a; }
button:focus-visible { outline: 3px solid #f3f4f6; outline-offset: 3px; }
.status { min-height: 24px; margin: 18px 0 20px; color: #c7d2e2; font-size: 15px; }
.status.success { color: #55e6b5; font-weight: 700; }
.status.error { color: #ff9b91; }
.attempts { padding-top: 18px; border-top: 1px solid #39465d; color: #9aa9bf; font-size: 12px; font-weight: 800; letter-spacing: .12em; }
.attempts strong { margin-left: 8px; color: #f3f4f6; font-size: 16px; letter-spacing: 0; }
@media (max-width: 380px) { .lock-card { padding: 28px 18px 24px; } .dial { width: 82px; } .dials { gap: 10px; } }

const dials = [...document.querySelectorAll('.dial')];
const status = document.querySelector('#status');
const attemptCount = document.querySelector('#attempt-count');
let attempts = 0;

dials.forEach((dial) => {
  const output = dial.querySelector('.digit');
  dial.querySelectorAll('[data-step]').forEach((button) => {
    button.addEventListener('click', () => {
      const current = Number(output.value);
      const step = Number(button.dataset.step);
      output.value = String((current + step + 10) % 10);
    });
  });
});

document.querySelector('#open-button').addEventListener('click', () => {
  const combination = dials.map((dial) => dial.querySelector('.digit').value).join('');
  if (combination === '372') {
    status.textContent = 'Access granted. The vault is open!';
    status.className = 'status success';
    return;
  }
  attempts += 1;
  attemptCount.textContent = String(attempts);
  status.textContent = 'Access denied. Try another combination.';
  status.className = 'status error';
});
